awk '!/^#/ {
    if (n == 0 || $2 < min) min = $2
    if (n == 0 || $2 > max) max = $2
    n += 1
}
END {
    print "min =", min
    print "max =", max
}' measurements.dat

cat > average.awk
!/^#/ {
    sum += $2
    n += 1
}

END {
    if (n > 0)
        print "average velocity =", sum/n
    else
        print "no data"
}
^D
